    'import { Button } from "@/components/ui/button"\nimport {\n  Card,\n  CardAction,\n  CardContent,\n  CardDescription,\n  CardFooter,\n  CardHeader,\n  CardTitle,\n} from "@/components/ui/card"\nimport { Field, FieldGroup, FieldLabel } from "@/components/ui/field"\nimport {\n  InputGroup,\n  InputGroupAddon,\n  InputGroupInput,\n  InputGroupText,\n} from "@/components/ui/input-group"\nimport { Item, ItemContent } from "@/components/ui/item"\nimport {\n  Select,\n  SelectContent,\n  SelectGroup,\n  SelectItem,\n  SelectTrigger,\n  SelectValue,\n} from "@/components/ui/select"\nimport { Separator } from "@/components/ui/separator"\n\nexport function TransferFunds() {\n  return (\n    <Card>\n      <CardHeader>\n        <CardTitle>Transfer Funds</CardTitle>\n        <CardDescription>\n          Move money between your connected accounts.\n        </CardDescription>\n        <CardAction>\n          <Button variant="ghost" size="icon-sm" className="bg-muted">\n            <IconPlaceholder\n              lucide="XIcon"\n              tabler="IconX"\n              hugeicons="Cancel01Icon"\n              phosphor="XIcon"\n              remixicon="RiCloseLine"\n            />\n          </Button>\n        </CardAction>\n      </CardHeader>\n      <CardContent>\n        <FieldGroup>\n          <Field>\n            <FieldLabel htmlFor="transfer-amount">\n              Amount to Transfer\n            </FieldLabel>\n            <InputGroup>\n              <InputGroupAddon>\n                <InputGroupText>$</InputGroupText>\n              </InputGroupAddon>\n              <InputGroupInput id="transfer-amount" defaultValue="1,200.00" />\n            </InputGroup>\n          </Field>\n          <Field>\n            <FieldLabel htmlFor="from-account">From Account</FieldLabel>\n            <Select defaultValue="checking">\n              <SelectTrigger id="from-account" className="w-full">\n                <SelectValue />\n              </SelectTrigger>\n              <SelectContent>\n                <SelectGroup>\n                  <SelectItem value="checking">\n                    Main Checking (··8402) — $12,450.00\n                  </SelectItem>\n                  <SelectItem value="business">\n                    Business (··7731) — $8,920.00\n                  </SelectItem>\n                </SelectGroup>\n              </SelectContent>\n            </Select>\n          </Field>\n          <Field>\n            <FieldLabel htmlFor="to-account">To Account</FieldLabel>\n            <Select defaultValue="savings">\n              <SelectTrigger id="to-account" className="w-full">\n                <SelectValue />\n              </SelectTrigger>\n              <SelectContent>\n                <SelectGroup>\n                  <SelectItem value="savings">\n                    High Yield Savings (··1192) — $42,100.00\n                  </SelectItem>\n                  <SelectItem value="investment">\n                    Investment (··3349) — $18,200.00\n                  </SelectItem>\n                </SelectGroup>\n              </SelectContent>\n            </Select>\n          </Field>\n          <Item variant="muted" className="flex-col items-stretch">\n            <ItemContent className="gap-3">\n              <div className="flex items-center justify-between">\n                <span className="text-sm text-muted-foreground">\n                  Estimated arrival\n                </span>\n                <span className="text-sm font-medium">Today, Apr 14</span>\n              </div>\n              <Separator />\n              <div className="flex items-center justify-between">\n                <span className="text-sm text-muted-foreground">\n                  Transaction fee\n                </span>\n                <span className="text-sm font-medium tabular-nums">$0.00</span>\n              </div>\n              <Separator />\n              <div className="flex items-center justify-between">\n                <span className="text-sm font-medium">Total amount</span>\n                <span className="text-sm font-semibold tabular-nums">\n                  $1,200.00\n                </span>\n              </div>\n            </ItemContent>\n          </Item>\n        </FieldGroup>\n      </CardContent>\n      <CardFooter>\n        <Button className="w-full">Confirm Transfer</Button>\n      </CardFooter>\n    </Card>\n  )\n}\n',
  'cards/upcoming-payments.tsx':
    '"use client"\n\nimport * as React from "react"\n\nimport { Badge } from "@/components/ui/badge"\nimport { Calendar } from "@/components/ui/calendar"\nimport {\n  Card,\n  CardContent,\n  CardDescription,\n  CardHeader,\n  CardTitle,\n} from "@/components/ui/card"\nimport {\n  Item,\n  ItemContent,\n  ItemDescription,\n  ItemGroup,\n  ItemMedia,\n  ItemTitle,\n} from "@/components/ui/item"\n\nexport function UpcomingPayments() {\n  const [date, setDate] = React.useState<Date | undefined>(new Date())\n\n  return (\n    <Card>\n      <CardHeader>\n        <CardTitle>Upcoming Payments</CardTitle>\n        <CardDescription>\n          Select a date to view scheduled payments.\n        </CardDescription>\n      </CardHeader>\n      <CardContent className="flex flex-col gap-4">\n        <Item variant="outline" className="justify-center">\n          <Calendar\n            mode="single"\n            selected={date}\n            onSelect={setDate}\n            className="w-full [--cell-size:--spacing(8)] md:[--cell-size:--spacing(10)] style-sera:md:[--cell-size:--spacing(9)]"\n          />\n        </Item>\n        <ItemGroup className="w-full">\n          <Item variant="muted">\n            <ItemContent>\n              <ItemTitle>Netflix Subscription</ItemTitle>\n              <ItemDescription>Apr 15, 2024</ItemDescription>\n            </ItemContent>\n            <Badge variant="secondary">$19.99</Badge>\n          </Item>\n          <Item variant="muted">\n            <ItemContent>\n              <ItemTitle>Rent Payment</ItemTitle>\n              <ItemDescription>Apr 1, 2024</ItemDescription>\n            </ItemContent>\n            <Badge variant="secondary">$2,400.00</Badge>\n          </Item>\n          <Item variant="muted">\n            <ItemContent>\n              <ItemTitle>Auto Insurance</ItemTitle>\n              <ItemDescription>Apr 22, 2024</ItemDescription>\n            </ItemContent>\n            <Badge variant="secondary">$186.00</Badge>\n          </Item>\n        </ItemGroup>\n      </CardContent>\n    </Card>\n  )\n}\n',
