const VARIANTS = { base: BASE, radix: RADIX, aria: ARIA } satisfies Record<ShadcnBase, Readonly<Record<string, string>>>;

export function createPreviewSources(base: ShadcnBase): Readonly<Record<string, string>> {
  return { ...COMMON, ...VARIANTS[base] };
}
